              </div>
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredApplications.length > 0 ? (
                filteredApplications.map(app => (
                  <div key={app.id} className="bg-white p-8 border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-8 items-start animate-in fade-in slide-in-from-bottom-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2"><h3 className="text-xl font-bold text-slate-900">{app.candidateName}</h3><span className="px-2 py-0.5 bg-brand-light text-brand text-[10px] font-bold uppercase rounded">{jobs.find(j => j.id === app.jobId)?.category || 'Altro'}</span></div>
                      <p className="text-sm text-slate-500 font-medium mb-1">Per: <span className="text-slate-900">{jobs.find(j => j.id === app.jobId)?.title || 'Posizione rimossa'}</span></p>
                      <p className="text-sm text-slate-500 font-medium mb-4">{app.email} &bull; {app.phone}</p>
                      <div className="bg-slate-50 p-5 border-l-4 border-brand italic text-slate-600 text-sm">"{app.coverLetter || 'Nessuna lettera.'}"</div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[180px] w-full sm:w-auto">
                      {app.cvFileName ? (
                        <button onClick={() => handleDownloadCV(app)} disabled={loadingCVId === app.id} className={`bg-slate-900 text-white px-6 py-3 text-sm font-bold text-center hover:bg-slate-800 transition-colors uppercase flex items-center justify-center gap-2 ${loadingCVId === app.id ? 'opacity-70' : ''}`}>
                          {loadingCVId === app.id ? <><div className="w-3 h-3 border-2 border-white border-t-transparent animate-spin rounded-full"></div>Recupero...</> : 'Scarica CV'}
                        </button>
                      ) : <div className="bg-slate-100 text-slate-400 px-6 py-3 text-xs font-bold text-center uppercase border border-slate-200">Nessun CV</div>}
                      <p className="text-[10px] text-center text-slate-400 font-bold uppercase">Ricevuto il: {new Date(app.appliedAt).toLocaleDateString('it-IT')}</p>
                    </div>
                  </div>
                ))
              ) : <div className="col-span-full bg-white border border-slate-200 p-20 text-center"><p className="text-slate-400 font-medium">Nessuna candidatura trovata.</p></div>}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {view === 'ADMIN_SETTINGS' && isAuthenticated && <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-6 lg:px-12"><JobForm initialData={editingJob || undefined} onSubmit={handleAddJob} onCancel={() => setView('ADMIN')} /></div>
        )}
      </main>
      {isApplyModalOpen && selectedJob && <ApplicationModal job={selectedJob} isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} onSubmit={handleApply} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Job, Application } from '../types';
import { Icons } from '../constants';

interface ApplicationModalProps {
  job: Job;
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (app: Omit<Application, 'id' | 'appliedAt'>) => void;
}

export const ApplicationModal: React.FC<ApplicationModalProps> = ({ job, isOpen, onClose, onSubmit }) => {
  const [formData, setFormData] = useState({
    candidateName: '',
    email: '',
    phone: '',
    coverLetter: '',
    cvFileName: '',
    consentGiven: false
  });
  const [cvBase64, setCvBase64] = useState('');
  const [attemptedSubmit, setAttemptedSubmit] = useState(false);

  // Blocco dello scroll della pagina sottostante quando il modal è aperto
  useEffect(() => {
    const html = document.documentElement;
    const body = document.body;

    if (isOpen) {
      const scrollBarWidth = window.innerWidth - html.clientWidth;
      html.style.overflow = 'hidden';
      body.style.overflow = 'hidden';
      body.style.paddingRight = `${scrollBarWidth}px`;
    } else {
      html.style.overflow = '';
      body.style.overflow = '';
      body.style.paddingRight = '';
    }

    return () => {
      html.style.overflow = '';
      body.style.overflow = '';
      body.style.paddingRight = '';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFormData(prev => ({ ...prev, cvFileName: file.name }));
      const reader = new FileReader();
      reader.onload = () => {
        setCvBase64(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setAttemptedSubmit(true);

    if (!formData.cvFileName || !cvBase64) {
      alert("Il caricamento del CV è obbligatorio per procedere con la candidatura.");
      return;
    }

    if (!formData.consentGiven) {
      alert("È necessario accettare il trattamento dei dati personali per procedere.");
      return;
    }

    onSubmit({
      ...formData,
      jobId: job.id,
      cvBase64
    });
  };

  return (
    <div className="fixed inset-0 z-[60] bg-slate-900/60 backdrop-blur-sm overflow-y-auto outline-none">
      <div className="flex min-h-full items-start justify-center p-4 sm:p-6">
        <div className="bg-white w-full max-w-2xl shadow-2xl p-6 sm:p-10 relative animate-in slide-in-from-top-4 duration-300 mt-4 mb-12 sm:my-12">
          {/* Tasto chiusura migliorato */}
          <button 
            onClick={onClose}
            className="absolute top-3 right-3 sm:top-6 sm:right-6 p-3 text-slate-400 hover:text-slate-900 hover:bg-slate-100 transition-all z-20 rounded-full"
            aria-label="Chiudi"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>

          <div className="pr-12 sm:pr-0 mb-8">
            <h2 className="text-xl sm:text-2xl font-bold text-slate-900 mb-1 leading-tight">Candidati per {job.title}</h2>
            <p className="text-sm text-slate-500">{job.location}</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="space-y-1.5">
                <label className="text-sm font-semibold text-slate-700">Nome e Cognome</label>
                <input
                  required
                  className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none text-base bg-white"
                  placeholder="Mario Rossi"
                  value={formData.candidateName}
                  onChange={e => setFormData({ ...formData, candidateName: e.target.value })}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-sm font-semibold text-slate-700">Email</label>
                <input
                  required
                  type="email"
                  className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none text-base bg-white"
                  placeholder="mario@esempio.it"
                  value={formData.email}
                  onChange={e => setFormData({ ...formData, email: e.target.value })}
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-700">Telefono</label>
              <input
                required
                type="tel"
                className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none text-base bg-white"
                placeholder="es. 3331234567"
                value={formData.phone}
                onChange={e => {
                  const val = e.target.value.replace(/\D/g, '');
                  setFormData({ ...formData, phone: val });
                }}
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-700 flex items-center gap-1.5">
                Carica CV (PDF o DOC) <span className="text-red-500 font-bold">*</span>
              </label>
              <div className="flex flex-col gap-2">
                <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                  <label className={`cursor-pointer px-6 py-3 border border-dashed hover:bg-slate-200 transition-colors font-bold text-center sm:text-left bg-slate-100 ${attemptedSubmit && !formData.cvFileName ? 'border-red-500 bg-red-50 text-red-600' : 'border-slate-300 text-slate-600'}`}>
                    Scegli file
                    <input type="file" className="hidden" accept=".pdf,.doc,.docx" onChange={handleFileChange} />
                  </label>
                  <span className={`text-sm italic truncate max-w-full block ${attemptedSubmit && !formData.cvFileName ? 'text-red-500 font-bold' : 'text-slate-500'}`}>
                    {formData.cvFileName || 'Nessun file selezionato (Obbligatorio)'}
                  </span>
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-700">Lettera di Presentazione (opzionale)</label>
              <textarea
                rows={4}
                className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none text-base bg-white"
                placeholder="Raccontaci perché sei la persona giusta..."
                value={formData.coverLetter}
                onChange={e => setFormData({ ...formData, coverLetter: e.target.value })}
              ></textarea>
            </div>

            <div className="bg-slate-50 p-5 border border-slate-200 space-y-4">
               <div className="flex items-start gap-3">
                  <input 
                    type="checkbox" 
                    id="privacy-consent"
                    className="mt-1 w-6 h-6 shrink-0 accent-brand cursor-pointer"
                    required
                    checked={formData.consentGiven}
                    onChange={e => setFormData({...formData, consentGiven: e.target.checked})}
                  />
                  <label htmlFor="privacy-consent" className="text-[11px] sm:text-xs text-slate-600 leading-tight cursor-pointer font-medium">
                    Dichiaro di aver letto l'<strong>Informativa sulla Privacy</strong> e acconsento al trattamento dei miei dati personali per finalità legate alla selezione del personale (GDPR).
                  </label>
               </div>
            </div>

            <div className="pt-2">
              <button
                type="submit"
                className="w-full py-5 bg-brand text-white font-bold text-lg hover:bg-brand-dark transition-all shadow-xl shadow-brand/20 disabled:opacity-50 disabled:grayscale uppercase tracking-widest active:scale-[0.98]"
              >
                Invia Candidatura
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Job, Application, ViewState, JobType, JobCategory } from './types';
import { Icons } from './constants';
import { JobCard } from './components/JobCard';
import { JobForm } from './components/JobForm';
import { ApplicationModal } from './components/ApplicationModal';
import { AdminModule } from './components/AdminModule';
import { CompanyProfile } from './components/CompanyProfile';
import { Settings } from './components/Settings';
import { ThankYou } from './components/ThankYou';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(() => {
    const savedView = localStorage.getItem('shs_job_view');
    if (savedView === 'JOB_DETAILS' || savedView === 'THANK_YOU') return 'PUBLIC';
    return (savedView as ViewState) || 'PUBLIC';
  });

  const [jobs, setJobs] = useState<Job[]>([]);
  const [applications, setApplications] = useState<Application[]>([]);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [editingJob, setEditingJob] = useState<Job | null>(null);
  const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);
  const [filterType, setFilterType] = useState<string>('All');
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isSubmittingApp, setIsSubmittingApp] = useState(false);
  const [loadingCVId, setLoadingCVId] = useState<string | null>(null);

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState<string | undefined>();
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [loginError, setLoginError] = useState('');

  const [appFilterCategory, setAppFilterCategory] = useState<string>('All');
  const [appFilterDateStart, setAppFilterDateStart] = useState<string>('');
  const [appFilterDateEnd, setAppFilterDateEnd] = useState<string>('');

  useEffect(() => {
    localStorage.setItem('shs_job_view', view);
  }, [view]);

  useEffect(() => {
    const checkAuth = async () => {
      setIsAuthLoading(true);
      const { data: { session } } = await supabase.auth.getSession();
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
      setIsAuthLoading(false);
    };
    checkAuth();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => { 
    fetchData(true); 
  }, []);

  useEffect(() => {
    if (view.startsWith('ADMIN') && isAuthenticated) fetchData(false); 
  }, [view, isAuthenticated]);

  const fetchData = async (showMainLoader = true) => {
    if (showMainLoader) setIsLoading(true);
    else setIsRefreshing(true);
    try {
      const { data: jobsData, error: jobsError } = await supabase
        .from('jobs')
        .select('*')
        .order('posted_at', { ascending: false });

      if (jobsError) throw jobsError;

      const mappedJobs: Job[] = (jobsData || []).map(j => ({
        id: j.id,
        title: j.title,
        company: j.company,
        category: j.category as JobCategory,
        type: j.type as JobType,
        location: j.location,
        description: j.description,
        requirements: j.requirements || [],
        salaryRange: j.salary_range,
        postedAt: j.posted_at,
        isFeatured: j.is_featured || false
      }));
      setJobs(mappedJobs);

      const { data: appsData, error: appsError } = await supabase
        .from('applications')
        .select('id, job_id, candidate_name, email, phone, cover_letter, cv_file_name, applied_at, consent_given')
        .order('applied_at', { ascending: false });

      if (!appsError && appsData) {
        const mappedApps: Application[] = appsData.map(a => ({
          id: a.id,
          jobId: a.job_id,
          candidateName: a.candidate_name,
          email: a.email,
          phone: a.phone,
          coverLetter: a.cover_letter,
          cvFileName: a.cv_file_name,
          cvBase64: '',
          appliedAt: a.applied_at,
          consentGiven: a.consent_given || false
        }));
        setApplications(mappedApps);
      } else {
        setApplications([]);
      }
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleDownloadCV = async (app: Application) => {
    if (!app.cvFileName || loadingCVId) return;
    setLoadingCVId(app.id);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('cv_base64')
        .eq('id', app.id)
        .single();
      if (error) throw error;
      const base64Data = data?.cv_base64;
      if (!base64Data) {
        alert("Contenuto del file non trovato.");
        return;
      }
      const link = document.createElement('a');
      link.href = base64Data;
      link.download = app.cvFileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err: any) {
      console.error("Errore recupero CV:", err);
      alert("Impossibile scaricare il file.");
    } finally {
      setLoadingCVId(null);
    }
  };

  const handleAddJob = async (jobData: Omit<Job, 'id' | 'postedAt'>) => {
    const dbJob: any = {
      title: jobData.title,
      company: jobData.company,
      category: jobData.category,
      type: jobData.type,
      location: jobData.location,
      description: jobData.description,
      requirements: jobData.requirements,
      salary_range: jobData.salaryRange,
      is_featured: jobData.isFeatured
    };
    const performSave = async (payload: any) => {
      if (editingJob) return await supabase.from('jobs').update(payload).eq('id', editingJob.id);
      else return await supabase.from('jobs').insert([{ ...payload, posted_at: new Date().toISOString() }]);
    };
    try {
      const { error } = await performSave(dbJob);
      if (error) throw error;
      await fetchData(false);
      setEditingJob(null);
      setView('ADMIN');
    } catch (err: any) {
      console.error("Errore salvataggio job:", err);
      alert("Errore nel salvataggio.");
    }
  };

  const handleApply = async (appData: Omit<Application, 'id' | 'appliedAt'>) => {
    setIsApplyModalOpen(false);
    setIsSubmittingApp(true);
    const appliedAt = new Date().toISOString();

    const dbApp: any = {
      job_id: appData.jobId,
      candidate_name: appData.candidateName,
      email: appData.email,
      phone: appData.phone,
      cover_letter: appData.coverLetter,
      cv_file_name: appData.cvFileName,
      cv_base64: appData.cvBase64,
      applied_at: appliedAt,
      consent_given: appData.consentGiven
    };

    try {
      // 1. Salvataggio su DB (Aperto a tutti gli utenti tramite RLS anonima)
      const { error: insertError } = await supabase.from('applications').insert([dbApp]);
      if (insertError) throw insertError;

      // 2. Recupero impostazioni webhook dall'azienda (Accessibile pubblicamente per permettere l'invio anonimo)
      const { data: profile } = await supabase
        .from('company_profiles')
        .select('notifications_enabled, webhook_url')
        .limit(1)
        .maybeSingle();

      // 3. Invio Webhook se configurato - Deve funzionare per ogni candidatura (anche anonima)
      if (profile?.notifications_enabled && profile?.webhook_url) {
        const job = jobs.find(j => j.id === appData.jobId);

        // Payload aggiornato: ora include cv_base64 e cv_file_name per permettere a Make di scaricare l'allegato
        const webhookPayload = {
          candidate_name: appData.candidateName,
          email: appData.email,
          phone: appData.phone,
          job_id: appData.jobId,
          job_title: job?.title || 'Posizione non specificata',
          cover_letter: appData.coverLetter,
          cv_file_name: appData.cvFileName,
          cv_base64: appData.cvBase64
        };

        // Invio asincrono al webhook.
        fetch(profile.webhook_url, {
          method: 'POST',
          mode: 'cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(webhookPayload)
        }).catch(err => console.warn("Errore durante l'invio al Webhook (CORS o URL errato):", err));
      }

      await fetchData(false); 
      setView('THANK_YOU');
    } catch (err: any) {
      console.error("Errore durante l'invio della candidatura:", err);
      alert("Errore durante l'invio: " + (err.message || 'Riprova più tardi.'));
    } finally {
      setIsSubmittingApp(false);
    }
  };

  const availableCategories = useMemo(() => {
    const cats = new Set<string>();
    jobs.forEach(j => cats.add(j.category));
    return Array.from(cats).sort();
  }, [jobs]);

  const stats = useMemo(() => {
    const totalJobs = jobs.length;
    const totalApps = applications.length;
    const avgAppsPerJob = totalJobs > 0 ? (totalApps / totalJobs).toFixed(1) : 0;
    const categoryDist = availableCategories.map(cat => ({
      name: cat,
      count: jobs.filter(j => j.category === cat).length,
      apps: applications.filter(a => jobs.find(j => j.id === a.jobId)?.category === cat).length
    }));
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const recentApps = applications.filter(a => new Date(a.appliedAt) > sevenDaysAgo).length;
    return { totalJobs, totalApps, avgAppsPerJob, categoryDist, recentApps };
  }, [jobs, applications, availableCategories]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    const { error } = await supabase.auth.signInWithPassword({
      email: loginForm.username,
      password: loginForm.password,
    });
    if (error) setLoginError('Credenziali non valide.');
    else setView('ADMIN');
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('PUBLIC');
  };

  const handleRemoveJob = async (id: string) => {
    if (!confirm("Eliminare questo annuncio?")) return;
    try {
      const { error } = await supabase.from('jobs').delete().eq('id', id);
      if (error) throw error;
      await fetchData(false);
    } catch (err) {
      console.error("Errore eliminazione:", err);
    }
  };

  const filteredAndSortedJobs = useMemo(() => {
    const filtered = filterType === 'All' 
      ? jobs 
      : jobs.filter(j => j.category === filterType);
    return [...filtered].sort((a, b) => {
      if (a.isFeatured && !b.isFeatured) return -1;
      if (!a.isFeatured && b.isFeatured) return 1;
      return new Date(b.postedAt).getTime() - new Date(a.postedAt).getTime();
    });
  }, [jobs, filterType]);

  const filteredApplications = useMemo(() => {
    return applications.filter(app => {
      const job = jobs.find(j => j.id === app.jobId);
      const categoryMatch = appFilterCategory === 'All' || (job && job.category === appFilterCategory);
      const appDate = new Date(app.appliedAt);
      const startMatch = !appFilterDateStart || appDate >= new Date(appFilterDateStart);
      const endMatch = !appFilterDateEnd || appDate <= new Date(appFilterDateEnd + 'T23:59:59');
      return categoryMatch && startMatch && endMatch;
    });
  }, [applications, jobs, appFilterCategory, appFilterDateStart, appFilterDateEnd]);

  if (isAuthLoading || isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-brand border-t-transparent animate-spin rounded-full"></div>
          <p className="text-slate-500 font-medium animate-pulse">Sincronizzazione in corso...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      {isSubmittingApp && (
        <div className="fixed inset-0 z-[100] bg-white/90 backdrop-blur-md flex items-center justify-center animate-in fade-in duration-300">
          <div className="flex flex-col items-center gap-6 text-center px-4">
            <div className="w-16 h-16 border-4 border-brand border-t-transparent animate-spin rounded-full shadow-lg"></div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900 mb-2">Stiamo inviando la tua candidatura</h2>
              <p className="text-slate-500 font-medium animate-pulse">Attendi qualche secondo, stiamo salvando i tuoi dati...</p>
            </div>
          </div>
        </div>
      )}

      <div className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[92vw] sm:w-auto">
        <div className="bg-white/80 backdrop-blur-md border border-slate-200 px-1 py-1 shadow-xl flex items-center gap-1 w-full sm:w-auto rounded-none">
          <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view === 'PUBLIC' || view === 'JOB_DETAILS' || view === 'THANK_YOU' ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Posizioni Aperte</button>
          <button onClick={() => setView('ADMIN')} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view.startsWith('ADMIN') ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Area Azienda</button>
        </div>
      </div>

      <main className="pt-8">
        {(view === 'PUBLIC' || (view === 'JOB_DETAILS' && !selectedJob)) && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="mb-12 text-center">
              <h1 className="text-4xl lg:text-5xl font-extrabold text-slate-900 mb-4 tracking-tight">Lavora con noi</h1>
              <p className="text-lg text-slate-600 max-w-2xl mx-auto">Sfoglia le nostre posizioni aperte e trova la tua prossima sfida professionale.</p>
            </div>
            <div className="flex flex-wrap gap-4 mb-10 justify-center">
              <button onClick={() => setFilterType('All')} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === 'All' ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>Tutti</button>
              {availableCategories.map(cat => (
                <button key={cat} onClick={() => setFilterType(cat)} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === cat ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>{cat}</button>
              ))}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-8">
              {filteredAndSortedJobs.length > 0 ? (
                filteredAndSortedJobs.map(job => (
                  <JobCard key={job.id} job={job} onClick={(j) => { setSelectedJob(j); setView('JOB_DETAILS'); }} />
                ))
              ) : (
                <div className="col-span-full py-20 text-center"><p className="text-slate-400 font-medium">Nessuna posizione trovata.</p></div>
              )}
            </div>
          </div>
        )}

        {view === 'JOB_DETAILS' && selectedJob && (
          <div className="w-full px-6 lg:px-20 py-32">
            <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 mb-8 font-medium group"><span className="group-hover:-translate-x-1 transition-transform"><Icons.ChevronLeft /></span>Torna agli annunci</button>
            <div className="bg-white border border-slate-200 p-8 md:p-16 shadow-sm">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 pb-10 border-b border-slate-100">
                <div>
                  <div className="flex items-center gap-3 mb-4">
                    <span className="inline-block px-3 py-1 text-xs font-bold bg-brand-light text-brand uppercase tracking-widest">{selectedJob.category}</span>
                    {selectedJob.isFeatured && <span className="inline-block px-3 py-1 text-xs font-bold bg-amber-100 text-amber-700 uppercase flex items-center gap-1.5"><Icons.Sparkles /> In Evidenza</span>}
                  </div>
                  <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 mb-2">{selectedJob.title}</h1>
                  <div className="flex flex-wrap gap-6 text-slate-500 font-medium mt-4">
                    <div className="flex items-center gap-2"><Icons.MapPin />{selectedJob.location}</div>
                    <div className="flex items-center gap-2"><Icons.Clock />{selectedJob.type}</div>
                  </div>
                </div>
                <button onClick={() => setIsApplyModalOpen(true)} className="bg-brand text-white px-10 py-5 font-bold text-xl hover:bg-brand-dark transition-all shadow-xl shadow-brand/20">Candidati Ora</button>
              </div>
              <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap mb-10 text-lg">{selectedJob.description}</div>
            </div>
          </div>
        )}

        {view === 'THANK_YOU' && <ThankYou onBack={() => { setView('PUBLIC'); setSelectedJob(null); }} jobTitle={selectedJob?.title} />}

        {view.startsWith('ADMIN') && !isAuthenticated && (
          <div className="max-w-md mx-auto px-4 py-32">
            <div className="bg-white p-8 border border-slate-200 shadow-2xl">
              <div className="text-center mb-8"><div className="inline-flex items-center justify-center w-16 h-16 bg-brand-light text-brand rounded-full mb-4"><Icons.Briefcase /></div><h2 className="text-2xl font-bold text-slate-900">Bentornato</h2><p className="text-slate-500 text-sm">Accedi per gestire la tua bacheca.</p></div>
              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Email</label><input type="email" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="email@azienda.it" value={loginForm.username} onChange={e => setLoginForm({ ...loginForm, username: e.target.value })} /></div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Password</label><input type="password" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="••••••••" value={loginForm.password} onChange={e => setLoginForm({ ...loginForm, password: e.target.value })} /></div>
                {loginError && <div className="bg-red-50 text-red-500 p-3 text-xs border border-red-100 font-medium">{loginError}</div>}
                <button type="submit" className="w-full py-4 bg-brand text-white font-bold hover:bg-brand-dark transition-all uppercase tracking-widest text-sm shadow-lg shadow-brand/20 mt-4">Accedi</button>
              </form>
            </div>
          </div>
        )}

        {view === 'ADMIN' && isAuthenticated && (
          <AdminModule jobs={jobs} applications={applications} stats={stats} onLogout={handleLogout} onCreateJob={() => setView('ADMIN_CREATE')} onViewApplications={() => setView('ADMIN_APPLICATIONS')} onEditJob={(job) => { setEditingJob(job); setView('ADMIN_EDIT'); }} onRemoveJob={handleRemoveJob} onNavigate={(newView) => setView(newView)} onRefresh={() => fetchData(false)} isRefreshing={isRefreshing} userEmail={userEmail} />
        )}

        {view === 'ADMIN_APPLICATIONS' && isAuthenticated && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <button onClick={() => setView('ADMIN')} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 font-medium"><Icons.ChevronLeft />Torna alla Dashboard</button>
              <button onClick={() => fetchData(false)} disabled={isRefreshing} className="text-brand text-sm font-bold flex items-center gap-2 hover:underline disabled:opacity-50"><div className={isRefreshing ? 'animate-spin' : ''}><Icons.Clock /></div>Aggiorna</button>
            </div>
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 mb-12">
              <div><h1 className="text-3xl font-bold text-slate-900">Registro Candidature ({filteredApplications.length})</h1><p className="text-slate-500 mt-1">Gestisci e filtra le persone che hanno risposto ai tuoi annunci.</p></div>
              <div className="flex flex-wrap items-center gap-4 bg-white p-4 border border-slate-200 shadow-sm">
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Categoria</label><select className="px-3 py-2 border border-slate-200 outline-none bg-white text-sm font-medium min-w-[150px]" value={appFilterCategory} onChange={e => setAppFilterCategory(e.target.value)}><option value="All">Tutte</option>{availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}</select></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Dal</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateStart} onChange={e => setAppFilterDateStart(e.target.value)} /></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Al</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateEnd} onChange={e => setAppFilterDateEnd(e.target.value)} /></div>
                <div className="flex flex-col gap-1 self-end"><button onClick={() => { setAppFilterCategory('All'); setAppFilterDateStart(''); setAppFilterDateEnd(''); }} className="px-4 py-2 text-xs font-bold text-brand hover:bg-brand-light transition-all border border-brand/20 uppercase tracking-widest">Reset</button></div>
              </div>
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredApplications.length > 0 ? (
                filteredApplications.map(app => (
                  <div key={app.id} className="bg-white p-8 border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-8 items-start animate-in fade-in slide-in-from-bottom-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2"><h3 className="text-xl font-bold text-slate-900">{app.candidateName}</h3><span className="px-2 py-0.5 bg-brand-light text-brand text-[10px] font-bold uppercase rounded">{jobs.find(j => j.id === app.jobId)?.category || 'Altro'}</span></div>
                      <p className="text-sm text-slate-500 font-medium mb-1">Per: <span className="text-slate-900">{jobs.find(j => j.id === app.jobId)?.title || 'Posizione rimossa'}</span></p>
                      <p className="text-sm text-slate-500 font-medium mb-4">{app.email} &bull; {app.phone}</p>
                      <div className="bg-slate-50 p-5 border-l-4 border-brand italic text-slate-600 text-sm">"{app.coverLetter || 'Nessuna lettera.'}"</div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[180px] w-full sm:w-auto">
                      {app.cvFileName ? (
                        <button onClick={() => handleDownloadCV(app)} disabled={loadingCVId === app.id} className={`bg-slate-900 text-white px-6 py-3 text-sm font-bold text-center hover:bg-slate-800 transition-colors uppercase flex items-center justify-center gap-2 ${loadingCVId === app.id ? 'opacity-70' : ''}`}>
                          {loadingCVId === app.id ? <><div className="w-3 h-3 border-2 border-white border-t-transparent animate-spin rounded-full"></div>Recupero...</> : 'Scarica CV'}
                        </button>
                      ) : <div className="bg-slate-100 text-slate-400 px-6 py-3 text-xs font-bold text-center uppercase border border-slate-200">Nessun CV</div>}
                      <p className="text-[10px] text-center text-slate-400 font-bold uppercase">Ricevuto il: {new Date(app.appliedAt).toLocaleDateString('it-IT')}</p>
                    </div>
                  </div>
                ))
              ) : <div className="col-span-full bg-white border border-slate-200 p-20 text-center"><p className="text-slate-400 font-medium">Nessuna candidatura trovata.</p></div>}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {view === 'ADMIN_SETTINGS' && isAuthenticated && <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-6 lg:px-12"><JobForm initialData={editingJob || undefined} onSubmit={handleAddJob} onCancel={() => setView('ADMIN')} /></div>
        )}
      </main>
      {isApplyModalOpen && selectedJob && <ApplicationModal job={selectedJob} isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} onSubmit={handleApply} />}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Job, Application, ViewState, JobType, JobCategory } from './types';
import { Icons } from './constants';
import { JobCard } from './components/JobCard';
import { JobForm } from './components/JobForm';
import { ApplicationModal } from './components/ApplicationModal';
import { AdminModule } from './components/AdminModule';
import { CompanyProfile } from './components/CompanyProfile';
import { Settings } from './components/Settings';
import { ThankYou } from './components/ThankYou';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(() => {
    const savedView = localStorage.getItem('shs_job_view');
    if (savedView === 'JOB_DETAILS' || savedView === 'THANK_YOU') return 'PUBLIC';
    return (savedView as ViewState) || 'PUBLIC';
  });

  const [jobs, setJobs] = useState<Job[]>([]);
  const [applications, setApplications] = useState<Application[]>([]);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [editingJob, setEditingJob] = useState<Job | null>(null);
  const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);
  const [filterType, setFilterType] = useState<string>('All');
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isSubmittingApp, setIsSubmittingApp] = useState(false);
  const [loadingCVId, setLoadingCVId] = useState<string | null>(null);

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState<string | undefined>();
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [loginError, setLoginError] = useState('');

  const [appFilterCategory, setAppFilterCategory] = useState<string>('All');
  const [appFilterDateStart, setAppFilterDateStart] = useState<string>('');
  const [appFilterDateEnd, setAppFilterDateEnd] = useState<string>('');

  useEffect(() => {
    localStorage.setItem('shs_job_view', view);
  }, [view]);

  useEffect(() => {
    const checkAuth = async () => {
      setIsAuthLoading(true);
      const { data: { session } } = await supabase.auth.getSession();
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
      setIsAuthLoading(false);
    };
    checkAuth();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => { 
    fetchData(true); 
  }, []);

  useEffect(() => {
    if (view.startsWith('ADMIN') && isAuthenticated) fetchData(false); 
  }, [view, isAuthenticated]);

  const fetchData = async (showMainLoader = true) => {
    if (showMainLoader) setIsLoading(true);
    else setIsRefreshing(true);
    try {
      const { data: jobsData, error: jobsError } = await supabase
        .from('jobs')
        .select('*')
        .order('posted_at', { ascending: false });

      if (jobsError) throw jobsError;

      const mappedJobs: Job[] = (jobsData || []).map(j => ({
        id: j.id,
        title: j.title,
        company: j.company,
        category: j.category as JobCategory,
        type: j.type as JobType,
        location: j.location,
        description: j.description,
        requirements: j.requirements || [],
        salaryRange: j.salary_range,
        postedAt: j.posted_at,
        isFeatured: j.is_featured || false
      }));
      setJobs(mappedJobs);

      const { data: appsData, error: appsError } = await supabase
        .from('applications')
        .select('id, job_id, candidate_name, email, phone, cover_letter, cv_file_name, applied_at, consent_given')
        .order('applied_at', { ascending: false });

      if (!appsError && appsData) {
        const mappedApps: Application[] = appsData.map(a => ({
          id: a.id,
          jobId: a.job_id,
          candidateName: a.candidate_name,
          email: a.email,
          phone: a.phone,
          coverLetter: a.cover_letter,
          cvFileName: a.cv_file_name,
          cvBase64: '',
          appliedAt: a.applied_at,
          consentGiven: a.consent_given || false
        }));
        setApplications(mappedApps);
      } else {
        setApplications([]);
      }
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleDownloadCV = async (app: Application) => {
    if (!app.cvFileName || loadingCVId) return;
    setLoadingCVId(app.id);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('cv_base64')
        .eq('id', app.id)
        .single();
      if (error) throw error;
      const base64Data = data?.cv_base64;
      if (!base64Data) {
        alert("Contenuto del file non trovato.");
        return;
      }
      const link = document.createElement('a');
      link.href = base64Data;
      link.download = app.cvFileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err: any) {
      console.error("Errore recupero CV:", err);
      alert("Impossibile scaricare il file.");
    } finally {
      setLoadingCVId(null);
    }
  };

  const handleAddJob = async (jobData: Omit<Job, 'id' | 'postedAt'>) => {
    const dbJob: any = {
      title: jobData.title,
      company: jobData.company,
      category: jobData.category,
      type: jobData.type,
      location: jobData.location,
      description: jobData.description,
      requirements: jobData.requirements,
      salary_range: jobData.salaryRange,
      is_featured: jobData.isFeatured
    };
    const performSave = async (payload: any) => {
      if (editingJob) return await supabase.from('jobs').update(payload).eq('id', editingJob.id);
      else return await supabase.from('jobs').insert([{ ...payload, posted_at: new Date().toISOString() }]);
    };
    try {
      const { error } = await performSave(dbJob);
      if (error) throw error;
      await fetchData(false);
      setEditingJob(null);
      setView('ADMIN');
    } catch (err: any) {
      console.error("Errore salvataggio job:", err);
      alert("Errore nel salvataggio.");
    }
  };

  const handleApply = async (appData: Omit<Application, 'id' | 'appliedAt'>) => {
    setIsApplyModalOpen(false);
    setIsSubmittingApp(true);
    const appliedAt = new Date().toISOString();

    const dbApp: any = {
      job_id: appData.jobId,
      candidate_name: appData.candidateName,
      email: appData.email,
      phone: appData.phone,
      cover_letter: appData.coverLetter,
      cv_file_name: appData.cvFileName,
      cv_base64: appData.cvBase64,
      applied_at: appliedAt,
      consent_given: appData.consentGiven
    };

    try {
      // 1. Salvataggio su DB (Aperto a tutti gli utenti tramite RLS anonima)
      const { error: insertError } = await supabase.from('applications').insert([dbApp]);
      if (insertError) throw insertError;

      // 2. Recupero impostazioni webhook dall'azienda (Accessibile pubblicamente per permettere l'invio anonimo)
      const { data: profile } = await supabase
        .from('company_profiles')
        .select('notifications_enabled, webhook_url')
        .limit(1)
        .maybeSingle();

      // 3. Invio Webhook se configurato - Deve funzionare per ogni candidatura (anche anonima)
      if (profile?.notifications_enabled && profile?.webhook_url) {
        const job = jobs.find(j => j.id === appData.jobId);

        // Payload aggiornato: ora include cv_base64 e cv_file_name per permettere a Make di scaricare l'allegato
        const webhookPayload = {
          candidate_name: appData.candidateName,
          email: appData.email,
          phone: appData.phone,
          job_id: appData.jobId,
          job_title: job?.title || 'Posizione non specificata',
          cover_letter: appData.coverLetter,
          cv_file_name: appData.cvFileName,
          cv_base64: appData.cvBase64
        };

        // Invio asincrono al webhook.
        fetch(profile.webhook_url, {
          method: 'POST',
          mode: 'cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(webhookPayload)
        }).catch(err => console.warn("Errore durante l'invio al Webhook (CORS o URL errato):", err));
      }

      await fetchData(false); 
      setView('THANK_YOU');
    } catch (err: any) {
      console.error("Errore durante l'invio della candidatura:", err);
      alert("Errore durante l'invio: " + (err.message || 'Riprova più tardi.'));
    } finally {
      setIsSubmittingApp(false);
    }
  };

  const availableCategories = useMemo(() => {
    const cats = new Set<string>();
    jobs.forEach(j => cats.add(j.category));
    return Array.from(cats).sort();
  }, [jobs]);

  const stats = useMemo(() => {
    const totalJobs = jobs.length;
    const totalApps = applications.length;
    const avgAppsPerJob = totalJobs > 0 ? (totalApps / totalJobs).toFixed(1) : 0;
    const categoryDist = availableCategories.map(cat => ({
      name: cat,
      count: jobs.filter(j => j.category === cat).length,
      apps: applications.filter(a => jobs.find(j => j.id === a.jobId)?.category === cat).length
    }));
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const recentApps = applications.filter(a => new Date(a.appliedAt) > sevenDaysAgo).length;
    return { totalJobs, totalApps, avgAppsPerJob, categoryDist, recentApps };
  }, [jobs, applications, availableCategories]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    const { error } = await supabase.auth.signInWithPassword({
      email: loginForm.username,
      password: loginForm.password,
    });
    if (error) setLoginError('Credenziali non valide.');
    else setView('ADMIN');
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('PUBLIC');
  };

  const handleRemoveJob = async (id: string) => {
    if (!confirm("Eliminare questo annuncio?")) return;
    try {
      const { error } = await supabase.from('jobs').delete().eq('id', id);
      if (error) throw error;
      await fetchData(false);
    } catch (err) {
      console.error("Errore eliminazione:", err);
    }
  };

  const filteredAndSortedJobs = useMemo(() => {
    const filtered = filterType === 'All' 
      ? jobs 
      : jobs.filter(j => j.category === filterType);
    return [...filtered].sort((a, b) => {
      if (a.isFeatured && !b.isFeatured) return -1;
      if (!a.isFeatured && b.isFeatured) return 1;
      return new Date(b.postedAt).getTime() - new Date(a.postedAt).getTime();
    });
  }, [jobs, filterType]);

  const filteredApplications = useMemo(() => {
    return applications.filter(app => {
      const job = jobs.find(j => j.id === app.jobId);
      const categoryMatch = appFilterCategory === 'All' || (job && job.category === appFilterCategory);
      const appDate = new Date(app.appliedAt);
      const startMatch = !appFilterDateStart || appDate >= new Date(appFilterDateStart);
      const endMatch = !appFilterDateEnd || appDate <= new Date(appFilterDateEnd + 'T23:59:59');
      return categoryMatch && startMatch && endMatch;
    });
  }, [applications, jobs, appFilterCategory, appFilterDateStart, appFilterDateEnd]);

  if (isAuthLoading || isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-brand border-t-transparent animate-spin rounded-full"></div>
          <p className="text-slate-500 font-medium animate-pulse">Sincronizzazione in corso...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      {isSubmittingApp && (
        <div className="fixed inset-0 z-[100] bg-white/90 backdrop-blur-md flex items-center justify-center animate-in fade-in duration-300">
          <div className="flex flex-col items-center gap-6 text-center px-4">
            <div className="w-16 h-16 border-4 border-brand border-t-transparent animate-spin rounded-full shadow-lg"></div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900 mb-2">Stiamo inviando la tua candidatura</h2>
              <p className="text-slate-500 font-medium animate-pulse">Attendi qualche secondo, stiamo salvando i tuoi dati...</p>
            </div>
          </div>
        </div>
      )}

      <div className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[92vw] sm:w-auto">
        <div className="bg-white/80 backdrop-blur-md border border-slate-200 px-1 py-1 shadow-xl flex items-center gap-1 w-full sm:w-auto rounded-none">
          <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view === 'PUBLIC' || view === 'JOB_DETAILS' || view === 'THANK_YOU' ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Posizioni Aperte</button>
          <button onClick={() => setView('ADMIN')} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view.startsWith('ADMIN') ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Area Azienda</button>
        </div>
      </div>

      <main className="pt-8">
        {(view === 'PUBLIC' || (view === 'JOB_DETAILS' && !selectedJob)) && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="mb-12 text-center">
              <h1 className="text-4xl lg:text-5xl font-extrabold text-slate-900 mb-4 tracking-tight">Lavora con noi</h1>
              <p className="text-lg text-slate-600 max-w-2xl mx-auto">Sfoglia le nostre posizioni aperte e trova la tua prossima sfida professionale.</p>
            </div>
            <div className="flex flex-wrap gap-4 mb-10 justify-center">
              <button onClick={() => setFilterType('All')} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === 'All' ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>Tutti</button>
              {availableCategories.map(cat => (
                <button key={cat} onClick={() => setFilterType(cat)} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === cat ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>{cat}</button>
              ))}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-8">
              {filteredAndSortedJobs.length > 0 ? (
                filteredAndSortedJobs.map(job => (
                  <JobCard key={job.id} job={job} onClick={(j) => { setSelectedJob(j); setView('JOB_DETAILS'); }} />
                ))
              ) : (
                <div className="col-span-full py-20 text-center"><p className="text-slate-400 font-medium">Nessuna posizione trovata.</p></div>
              )}
            </div>
          </div>
        )}

        {view === 'JOB_DETAILS' && selectedJob && (
          <div className="w-full px-6 lg:px-20 py-32">
            <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 mb-8 font-medium group"><span className="group-hover:-translate-x-1 transition-transform"><Icons.ChevronLeft /></span>Torna agli annunci</button>
            <div className="bg-white border border-slate-200 p-8 md:p-16 shadow-sm">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 pb-10 border-b border-slate-100">
                <div>
                  <div className="flex items-center gap-3 mb-4">
                    <span className="inline-block px-3 py-1 text-xs font-bold bg-brand-light text-brand uppercase tracking-widest">{selectedJob.category}</span>
                    {selectedJob.isFeatured && <span className="inline-block px-3 py-1 text-xs font-bold bg-amber-100 text-amber-700 uppercase flex items-center gap-1.5"><Icons.Sparkles /> In Evidenza</span>}
                  </div>
                  <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 mb-2">{selectedJob.title}</h1>
                  <div className="flex flex-wrap gap-6 text-slate-500 font-medium mt-4">
                    <div className="flex items-center gap-2"><Icons.MapPin />{selectedJob.location}</div>
                    <div className="flex items-center gap-2"><Icons.Clock />{selectedJob.type}</div>
                  </div>
                </div>
                <button onClick={() => setIsApplyModalOpen(true)} className="bg-brand text-white px-10 py-5 font-bold text-xl hover:bg-brand-dark transition-all shadow-xl shadow-brand/20">Candidati Ora</button>
              </div>
              <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap mb-10 text-lg">{selectedJob.description}</div>
            </div>
          </div>
        )}

        {view === 'THANK_YOU' && <ThankYou onBack={() => { setView('PUBLIC'); setSelectedJob(null); }} jobTitle={selectedJob?.title} />}

        {view.startsWith('ADMIN') && !isAuthenticated && (
          <div className="max-w-md mx-auto px-4 py-32">
            <div className="bg-white p-8 border border-slate-200 shadow-2xl">
              <div className="text-center mb-8"><div className="inline-flex items-center justify-center w-16 h-16 bg-brand-light text-brand rounded-full mb-4"><Icons.Briefcase /></div><h2 className="text-2xl font-bold text-slate-900">Bentornato</h2><p className="text-slate-500 text-sm">Accedi per gestire la tua bacheca.</p></div>
              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Email</label><input type="email" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="email@azienda.it" value={loginForm.username} onChange={e => setLoginForm({ ...loginForm, username: e.target.value })} /></div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Password</label><input type="password" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="••••••••" value={loginForm.password} onChange={e => setLoginForm({ ...loginForm, password: e.target.value })} /></div>
                {loginError && <div className="bg-red-50 text-red-500 p-3 text-xs border border-red-100 font-medium">{loginError}</div>}
                <button type="submit" className="w-full py-4 bg-brand text-white font-bold hover:bg-brand-dark transition-all uppercase tracking-widest text-sm shadow-lg shadow-brand/20 mt-4">Accedi</button>
              </form>
            </div>
          </div>
        )}

        {view === 'ADMIN' && isAuthenticated && (
          <AdminModule jobs={jobs} applications={applications} stats={stats} onLogout={handleLogout} onCreateJob={() => setView('ADMIN_CREATE')} onViewApplications={() => setView('ADMIN_APPLICATIONS')} onEditJob={(job) => { setEditingJob(job); setView('ADMIN_EDIT'); }} onRemoveJob={handleRemoveJob} onNavigate={(newView) => setView(newView)} onRefresh={() => fetchData(false)} isRefreshing={isRefreshing} userEmail={userEmail} />
        )}

        {view === 'ADMIN_APPLICATIONS' && isAuthenticated && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <button onClick={() => setView('ADMIN')} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 font-medium"><Icons.ChevronLeft />Torna alla Dashboard</button>
              <button onClick={() => fetchData(false)} disabled={isRefreshing} className="text-brand text-sm font-bold flex items-center gap-2 hover:underline disabled:opacity-50"><div className={isRefreshing ? 'animate-spin' : ''}><Icons.Clock /></div>Aggiorna</button>
            </div>
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 mb-12">
              <div><h1 className="text-3xl font-bold text-slate-900">Registro Candidature ({filteredApplications.length})</h1><p className="text-slate-500 mt-1">Gestisci e filtra le persone che hanno risposto ai tuoi annunci.</p></div>
              <div className="flex flex-wrap items-center gap-4 bg-white p-4 border border-slate-200 shadow-sm">
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Categoria</label><select className="px-3 py-2 border border-slate-200 outline-none bg-white text-sm font-medium min-w-[150px]" value={appFilterCategory} onChange={e => setAppFilterCategory(e.target.value)}><option value="All">Tutte</option>{availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}</select></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Dal</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateStart} onChange={e => setAppFilterDateStart(e.target.value)} /></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Al</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateEnd} onChange={e => setAppFilterDateEnd(e.target.value)} /></div>
                <div className="flex flex-col gap-1 self-end"><button onClick={() => { setAppFilterCategory('All'); setAppFilterDateStart(''); setAppFilterDateEnd(''); }} className="px-4 py-2 text-xs font-bold text-brand hover:bg-brand-light transition-all border border-brand/20 uppercase tracking-widest">Reset</button></div>
              </div>
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredApplications.length > 0 ? (
                filteredApplications.map(app => (
                  <div key={app.id} className="bg-white p-8 border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-8 items-start animate-in fade-in slide-in-from-bottom-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2"><h3 className="text-xl font-bold text-slate-900">{app.candidateName}</h3><span className="px-2 py-0.5 bg-brand-light text-brand text-[10px] font-bold uppercase rounded">{jobs.find(j => j.id === app.jobId)?.category || 'Altro'}</span></div>
                      <p className="text-sm text-slate-500 font-medium mb-1">Per: <span className="text-slate-900">{jobs.find(j => j.id === app.jobId)?.title || 'Posizione rimossa'}</span></p>
                      <p className="text-sm text-slate-500 font-medium mb-4">{app.email} &bull; {app.phone}</p>
                      <div className="bg-slate-50 p-5 border-l-4 border-brand italic text-slate-600 text-sm">"{app.coverLetter || 'Nessuna lettera.'}"</div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[180px] w-full sm:w-auto">
                      {app.cvFileName ? (
                        <button onClick={() => handleDownloadCV(app)} disabled={loadingCVId === app.id} className={`bg-slate-900 text-white px-6 py-3 text-sm font-bold text-center hover:bg-slate-800 transition-colors uppercase flex items-center justify-center gap-2 ${loadingCVId === app.id ? 'opacity-70' : ''}`}>
                          {loadingCVId === app.id ? <><div className="w-3 h-3 border-2 border-white border-t-transparent animate-spin rounded-full"></div>Recupero...</> : 'Scarica CV'}
                        </button>
                      ) : <div className="bg-slate-100 text-slate-400 px-6 py-3 text-xs font-bold text-center uppercase border border-slate-200">Nessun CV</div>}
                      <p className="text-[10px] text-center text-slate-400 font-bold uppercase">Ricevuto il: {new Date(app.appliedAt).toLocaleDateString('it-IT')}</p>
                    </div>
                  </div>
                ))
              ) : <div className="col-span-full bg-white border border-slate-200 p-20 text-center"><p className="text-slate-400 font-medium">Nessuna candidatura trovata.</p></div>}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {view === 'ADMIN_SETTINGS' && isAuthenticated && <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-6 lg:px-12"><JobForm initialData={editingJob || undefined} onSubmit={handleAddJob} onCancel={() => setView('ADMIN')} /></div>
        )}
      </main>
      {isApplyModalOpen && selectedJob && <ApplicationModal job={selectedJob} isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} onSubmit={handleApply} />}
    </div>
  );
};

// Fixed error in index.tsx: Module '"file:///App"' has no default export.
export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Job, Application, ViewState } from '../types';
import { Icons } from '../constants';
import { StatsGrid } from './StatsGrid';

interface AdminModuleProps {
  jobs: Job[];
  applications: Application[];
  onLogout: () => void;
  onCreateJob: () => void;
  onViewApplications: () => void;
  // Added Job type to parameter to fix implicit any error
  onEditJob: (job: Job) => void;
  onRemoveJob: (id: string) => void;
  onNavigate: (view: ViewState) => void;
  onRefresh: () => void;
  isRefreshing?: boolean;
  stats: any;
  userEmail?: string;
}

type TimeScale = 'Daily' | 'Weekly' | 'Monthly' | 'Custom';

export const AdminModule: React.FC<AdminModuleProps> = ({
  jobs,
  applications,
  onLogout,
  onCreateJob,
  onViewApplications,
  onEditJob,
  onRemoveJob,
  onNavigate,
  onRefresh,
  isRefreshing,
  stats,
  userEmail
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [timeScale, setTimeScale] = useState<TimeScale>('Monthly');
  const [customRange, setCustomRange] = useState({ start: '', end: '' });
  const menuRef = useRef<HTMLDivElement>(null);

  const initials = userEmail ? userEmail.substring(0, 2).toUpperCase() : 'AD';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const chartData = useMemo(() => {
    const now = new Date();
    let periods: { label: string; count: number }[] = [];

    if (timeScale === 'Daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date();
        d.setDate(now.getDate() - i);
        const label = d.toLocaleDateString('it-IT', { weekday: 'short' });
        const count = applications.filter(app => {
          const appDate = new Date(app.appliedAt);
          return appDate.toDateString() === d.toDateString();
        }).length;
        periods.push({ label, count });
      }
    } else if (timeScale === 'Weekly') {
      for (let i = 3; i >= 0; i--) {
        const start = new Date();
        start.setDate(now.getDate() - (i * 7 + 7));
        const end = new Date();
        end.setDate(now.getDate() - (i * 7));
        const label = `Sett ${4-i}`;
        const count = applications.filter(app => {
          const appDate = new Date(app.appliedAt);
          return appDate >= start && appDate <= end;
        }).length;
        periods.push({ label, count });
      }
    } else if (timeScale === 'Monthly') {
      for (let i = 5; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const label = d.toLocaleDateString('it-IT', { month: 'short' }).toUpperCase();
        const count = applications.filter(app => {
          const appDate = new Date(app.appliedAt);
          return appDate.getMonth() === d.getMonth() && appDate.getFullYear() === d.getFullYear();
        }).length;
        periods.push({ label, count });
      }
    } else if (timeScale === 'Custom' && customRange.start && customRange.end) {
      const start = new Date(customRange.start);
      const end = new Date(customRange.end);
      const diffTime = Math.abs(end.getTime() - start.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      const step = Math.max(1, Math.floor(diffDays / 6));
      for (let i = 0; i <= 6; i++) {
        const currentStart = new Date(start);
        currentStart.setDate(start.getDate() + (i * step));
        const currentEnd = new Date(currentStart);
        currentEnd.setDate(currentStart.getDate() + step);

        const label = currentStart.toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit' });
        const count = applications.filter(app => {
          const appDate = new Date(currentStart); // Corrected to use currentStart for range check
          return appDate >= currentStart && appDate < currentEnd;
        }).length;
        periods.push({ label, count });
      }
    } else {
      periods = Array(6).fill(0).map((_, i) => ({ label: `T${i+1}`, count: 0 }));
    }

    const maxCount = Math.max(...periods.map(p => p.count), 1);
    return periods.map(p => ({ ...p, percentage: (p.count / maxCount) * 100 }));
  }, [applications, timeScale, customRange]);

  return (
    <div className="w-full px-6 lg:px-12 py-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
        <div>
          <h1 className="text-3xl lg:text-4xl font-bold text-slate-900 tracking-tight">Dashboard Amministratore</h1>
          <p className="text-slate-500 mt-1">Gestisci le tue posizioni aperte e monitora le performance.</p>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={onRefresh}
            disabled={isRefreshing}
            className="p-3 bg-white border border-slate-200 text-slate-500 hover:text-brand transition-all hover:bg-brand-light disabled:opacity-50"
          >
            <div className={isRefreshing ? 'animate-spin' : ''}>
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg>
            </div>
          </button>

          <div className="relative" ref={menuRef}>
            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="flex items-center gap-3 bg-white border border-slate-200 pl-2 pr-4 py-2 hover:bg-slate-50 transition-all shadow-sm"
            >
              <div className="w-9 h-9 bg-brand text-white flex items-center justify-center font-bold text-sm">
                {initials}
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">Account</p>
                <p className="text-sm font-semibold text-slate-700 truncate max-w-[150px]">{userEmail?.split('@')[0]}</p>
              </div>
              <Icons.ChevronDown />
            </button>

            {isMenuOpen && (
              <div className="absolute right-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl z-50 animate-in fade-in slide-in-from-top-2 duration-200">
                <div className="p-4 border-b border-slate-100 bg-slate-50/50">
                  <p className="text-xs font-bold text-slate-400 uppercase mb-1">Accesso effettuato come</p>
                  <p className="text-sm font-semibold text-slate-900 truncate">{userEmail}</p>
                </div>
                <div className="p-2">
                  <button onClick={() => { onNavigate('ADMIN_PROFILE'); setIsMenuOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 hover:text-brand transition-colors text-left"><Icons.User /> Profilo Aziendale</button>
                  <button onClick={() => { onNavigate('ADMIN_SETTINGS'); setIsMenuOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 hover:text-brand transition-colors text-left"><Icons.Settings /> Impostazioni SaaS</button>
                </div>
                <div className="p-2 border-t border-slate-100">
                  <button onClick={onLogout} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-red-500 hover:bg-red-50 transition-colors font-semibold text-left"><Icons.LogOut /> Esci dal sistema</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="flex gap-4 mb-8">
        <button onClick={onCreateJob} className="flex items-center gap-2 bg-brand text-white px-8 py-4 font-bold hover:bg-brand-dark transition-all shadow-lg shadow-brand/20"><Icons.Plus /> Nuova Posizione</button>
        <button onClick={onViewApplications} className="flex items-center gap-2 bg-white text-slate-700 border border-slate-200 px-8 py-4 font-bold hover:bg-slate-50 transition-all">
          <Icons.Users /> Visualizza Candidature ({applications.length})
        </button>
      </div>

      <StatsGrid 
        stats={[
          { label: 'Posizioni Attive', value: stats.totalJobs, trend: 'Dashboard Live', trendColor: 'text-brand' },
          { label: 'Candidati Totali', value: stats.totalApps, trend: `+${stats.recentApps} ultimi 7gg`, trendColor: 'text-blue-600' },
          { label: 'Media Candidati', value: stats.avgAppsPerJob, trend: 'Ottimo engagement' },
          { label: 'Tasso AI', value: '100%', trend: 'Assistente attivo', trendColor: 'text-brand' }
        ]}
      />

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 mb-12">
        <div className="bg-white border border-slate-200 p-8 shadow-sm">
          <h3 className="text-xl font-bold text-slate-900 mb-8 flex items-center gap-2">
             <Icons.Briefcase />
             Candidature per Categoria
          </h3>
          <div className="space-y-6">
            {stats.categoryDist.map((cat: any, idx: number) => (
              <div key={idx}>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-semibold text-slate-700">{cat.name}</span>
                  <span className="text-xs font-bold text-brand uppercase">{cat.apps} Candidati</span>
                </div>
                <div className="w-full bg-slate-100 h-3 overflow-hidden">
                  <div 
                    className="bg-brand h-full transition-all duration-1000"
                    style={{ width: `${Math.max(5, (cat.apps / (stats.totalApps || 1)) * 100)}%` }}
                  ></div>
                </div>
              </div>
            ))}
            {stats.categoryDist.length === 0 && <p className="text-slate-400 text-sm italic">Nessun dato disponibile.</p>}
          </div>
        </div>

        <div className="bg-white border border-slate-200 p-8 shadow-sm flex flex-col">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-10">
            <h3 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <Icons.Clock />
              Engagement Candidati
            </h3>
            <div className="flex bg-slate-100 p-1 rounded-lg">
              {(['Daily', 'Weekly', 'Monthly', 'Custom'] as TimeScale[]).map(s => (
                <button
                  key={s}
                  onClick={() => setTimeScale(s)}
                  className={`px-4 py-1.5 text-xs font-bold uppercase tracking-tighter transition-all rounded-md ${timeScale === s ? 'bg-white text-brand shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  {s === 'Daily' ? 'Giorno' : s === 'Weekly' ? 'Sett' : s === 'Monthly' ? 'Mese' : 'Data'}
                </button>
              ))}
            </div>
          </div>

          {timeScale === 'Custom' && (
            <div className="grid grid-cols-2 gap-4 mb-6 animate-in slide-in-from-top-1 duration-300">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Dal</label>
                <input 
                  type="date" 
                  className="w-full px-3 py-2 border border-slate-200 outline-none focus:ring-1 focus:ring-brand" 
                  value={customRange.start}
                  onChange={e => setCustomRange({...customRange, start: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Al</label>
                <input 
                  type="date" 
                  className="w-full px-3 py-2 border border-slate-200 outline-none focus:ring-1 focus:ring-brand" 
                  value={customRange.end}
                  onChange={e => setCustomRange({...customRange, end: e.target.value})}
                />
              </div>
            </div>
          )}

          <div className="flex items-end gap-5 h-64 pt-6 flex-1">
            {chartData.map((data, idx) => (
              <div key={idx} className="flex-1 flex flex-col items-center gap-4 h-full justify-end group">
                <div className="opacity-0 group-hover:opacity-100 transition-opacity bg-slate-900 text-white text-xs px-2.5 py-1 rounded font-bold mb-1">
                  {data.count}
                </div>
                <div 
                  className={`w-full ${data.percentage > 0 ? 'bg-brand' : 'bg-slate-100'} transition-all duration-700 hover:bg-brand-dark cursor-pointer shadow-sm`}
                  style={{ height: `${Math.max(2, data.percentage)}%` }}
                ></div>
                <span className="text-[10px] font-bold text-slate-400 uppercase truncate w-full text-center">{data.label}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-8 border-b border-slate-200 bg-slate-50/50 flex justify-between items-center">
          <h3 className="text-xl font-bold text-slate-900">Gestione Annunci</h3>
          <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">{jobs.length} Posizioni</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase tracking-wider">Posizione</th>
                <th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase tracking-wider">Categoria</th>
                <th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase tracking-wider">Candidati</th>
                <th className="px-8 py-5 text-sm font-bold text-slate-600 uppercase tracking-wider text-right">Azioni</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
              {jobs.map(job => (
                <tr key={job.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-8 py-6 font-bold text-slate-900 group-hover:text-brand transition-colors text-lg">{job.title}</td>
                  <td className="px-8 py-6 text-slate-500">
                    <span className="px-3 py-1.5 bg-slate-100 text-xs font-bold uppercase rounded">{job.category}</span>
                  </td>
                  <td className="px-8 py-6 text-slate-500 text-lg font-bold">
                    {applications.filter(a => a.jobId === job.id).length}
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-3">
                      <button onClick={() => onEditJob(job)} className="text-brand p-3 hover:bg-brand-light transition-all rounded-full"><Icons.Edit /></button>
                      <button onClick={() => onRemoveJob(job.id)} className="text-red-500 p-3 hover:bg-red-50 transition-all rounded-full"><Icons.Trash /></button>
                    </div>
                  </td>
                </tr>
              ))}
              {jobs.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-8 py-24 text-center text-slate-400 text-lg">Nessun annuncio pubblicato. Inizia ora!</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Job, Application, ViewState, JobType, JobCategory } from './types';
import { Icons } from './constants';
import { JobCard } from './components/JobCard';
import { JobForm } from './components/JobForm';
import { ApplicationModal } from './components/ApplicationModal';
import { AdminModule } from './components/AdminModule';
import { CompanyProfile } from './components/CompanyProfile';
import { Settings } from './components/Settings';
import { ThankYou } from './components/ThankYou';
import { supabase } from './supabaseClient';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(() => {
    const savedView = localStorage.getItem('shs_job_view');
    if (savedView === 'JOB_DETAILS' || savedView === 'THANK_YOU') return 'PUBLIC';
    return (savedView as ViewState) || 'PUBLIC';
  });

  const [jobs, setJobs] = useState<Job[]>([]);
  const [applications, setApplications] = useState<Application[]>([]);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [editingJob, setEditingJob] = useState<Job | null>(null);
  const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);
  const [filterType, setFilterType] = useState<string>('All');
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isSubmittingApp, setIsSubmittingApp] = useState(false);
  const [loadingCVId, setLoadingCVId] = useState<string | null>(null);
  const [isAiEnabled, setIsAiEnabled] = useState(true);

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userEmail, setUserEmail] = useState<string | undefined>();
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [loginError, setLoginError] = useState('');

  const [appFilterCategory, setAppFilterCategory] = useState<string>('All');
  const [appFilterDateStart, setAppFilterDateStart] = useState<string>('');
  const [appFilterDateEnd, setAppFilterDateEnd] = useState<string>('');

  useEffect(() => {
    localStorage.setItem('shs_job_view', view);
  }, [view]);

  useEffect(() => {
    const checkAuth = async () => {
      setIsAuthLoading(true);
      const { data: { session } } = await supabase.auth.getSession();
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
      setIsAuthLoading(false);
    };
    checkAuth();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const isAuth = !!session;
      setIsAuthenticated(isAuth);
      setUserEmail(session?.user?.email);
      if (!isAuth && view.startsWith('ADMIN')) setView('PUBLIC');
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => { 
    fetchData(true); 
  }, []);

  useEffect(() => {
    if (view.startsWith('ADMIN') && isAuthenticated) fetchData(false); 
  }, [view, isAuthenticated]);

  const fetchData = async (showMainLoader = true) => {
    if (showMainLoader) setIsLoading(true);
    else setIsRefreshing(true);
    try {
      const { data: jobsData, error: jobsError } = await supabase
        .from('jobs')
        .select('*')
        .order('posted_at', { ascending: false });

      if (jobsError) throw jobsError;

      const mappedJobs: Job[] = (jobsData || []).map(j => ({
        id: j.id,
        title: j.title,
        company: j.company,
        category: j.category as JobCategory,
        type: j.type as JobType,
        location: j.location,
        description: j.description,
        requirements: j.requirements || [],
        salaryRange: j.salary_range,
        postedAt: j.posted_at,
        isFeatured: j.is_featured || false
      }));
      setJobs(mappedJobs);

      const { data: appsData, error: appsError } = await supabase
        .from('applications')
        .select('id, job_id, candidate_name, email, phone, cover_letter, cv_file_name, applied_at, consent_given')
        .order('applied_at', { ascending: false });

      if (!appsError && appsData) {
        const mappedApps: Application[] = appsData.map(a => ({
          id: a.id,
          jobId: a.job_id,
          candidateName: a.candidate_name,
          email: a.email,
          phone: a.phone,
          coverLetter: a.cover_letter,
          cvFileName: a.cv_file_name,
          cvBase64: '',
          appliedAt: a.applied_at,
          consentGiven: a.consent_given || false
        }));
        setApplications(mappedApps);
      } else {
        setApplications([]);
      }

      // Recupero impostazioni profilo (AI Enabled)
      const { data: profile } = await supabase
        .from('company_profiles')
        .select('ai_assist_enabled')
        .limit(1)
        .maybeSingle();

      if (profile) {
        setIsAiEnabled(profile.ai_assist_enabled ?? true);
      }

    } catch (err) {
      console.error("Errore caricamento dati:", err);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleDownloadCV = async (app: Application) => {
    if (!app.cvFileName || loadingCVId) return;
    setLoadingCVId(app.id);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('cv_base64')
        .eq('id', app.id)
        .single();
      if (error) throw error;
      const base64Data = data?.cv_base64;
      if (!base64Data) {
        alert("Contenuto del file non trovato.");
        return;
      }
      const link = document.createElement('a');
      link.href = base64Data;
      link.download = app.cvFileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err: any) {
      console.error("Errore recupero CV:", err);
      alert("Impossibile scaricare il file.");
    } finally {
      setLoadingCVId(null);
    }
  };

  const handleAddJob = async (jobData: Omit<Job, 'id' | 'postedAt'>) => {
    const dbJob: any = {
      title: jobData.title,
      company: jobData.company,
      category: jobData.category,
      type: jobData.type,
      location: jobData.location,
      description: jobData.description,
      requirements: jobData.requirements,
      salary_range: jobData.salaryRange,
      is_featured: jobData.isFeatured
    };
    const performSave = async (payload: any) => {
      if (editingJob) return await supabase.from('jobs').update(payload).eq('id', editingJob.id);
      else return await supabase.from('jobs').insert([{ ...payload, posted_at: new Date().toISOString() }]);
    };
    try {
      const { error } = await performSave(dbJob);
      if (error) throw error;
      await fetchData(false);
      setEditingJob(null);
      setView('ADMIN');
    } catch (err: any) {
      console.error("Errore salvataggio job:", err);
      alert("Errore nel salvataggio.");
    }
  };

  const handleApply = async (appData: Omit<Application, 'id' | 'appliedAt'>) => {
    setIsApplyModalOpen(false);
    setIsSubmittingApp(true);
    const appliedAt = new Date().toISOString();

    const dbApp: any = {
      job_id: appData.jobId,
      candidate_name: appData.candidateName,
      email: appData.email,
      phone: appData.phone,
      cover_letter: appData.coverLetter,
      cv_file_name: appData.cvFileName,
      cv_base64: appData.cvBase64,
      applied_at: appliedAt,
      consent_given: appData.consentGiven
    };

    try {
      // 1. Salvataggio su DB (Aperto a tutti gli utenti tramite RLS anonima)
      const { error: insertError } = await supabase.from('applications').insert([dbApp]);
      if (insertError) throw insertError;

      // 2. Recupero impostazioni webhook dall'azienda (Accessibile pubblicamente per permettere l'invio anonimo)
      const { data: profile } = await supabase
        .from('company_profiles')
        .select('notifications_enabled, webhook_url')
        .limit(1)
        .maybeSingle();

      // 3. Invio Webhook se configurato - Deve funzionare per ogni candidatura (anche anonima)
      if (profile?.notifications_enabled && profile?.webhook_url) {
        const job = jobs.find(j => j.id === appData.jobId);

        // Payload aggiornato: ora include cv_base64 e cv_file_name per permettere a Make di scaricare l'allegato
        const webhookPayload = {
          candidate_name: appData.candidateName,
          email: appData.email,
          phone: appData.phone,
          job_id: appData.jobId,
          job_title: job?.title || 'Posizione non specificata',
          cover_letter: appData.coverLetter,
          cv_file_name: appData.cvFileName,
          cv_base64: appData.cvBase64
        };

        // Invio asincrono al webhook.
        fetch(profile.webhook_url, {
          method: 'POST',
          mode: 'cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(webhookPayload)
        }).catch(err => console.warn("Errore durante l'invio al Webhook (CORS o URL errato):", err));
      }

      await fetchData(false); 
      setView('THANK_YOU');
    } catch (err: any) {
      console.error("Errore durante l'invio della candidatura:", err);
      alert("Errore durante l'invio: " + (err.message || 'Riprova più tardi.'));
    } finally {
      setIsSubmittingApp(false);
    }
  };

  const availableCategories = useMemo(() => {
    const cats = new Set<string>();
    jobs.forEach(j => cats.add(j.category));
    return Array.from(cats).sort();
  }, [jobs]);

  const stats = useMemo(() => {
    const totalJobs = jobs.length;
    const totalApps = applications.length;
    const avgAppsPerJob = totalJobs > 0 ? (totalApps / totalJobs).toFixed(1) : 0;
    const categoryDist = availableCategories.map(cat => ({
      name: cat,
      count: jobs.filter(j => j.category === cat).length,
      apps: applications.filter(a => jobs.find(j => j.id === a.jobId)?.category === cat).length
    }));
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const recentApps = applications.filter(a => new Date(a.appliedAt) > sevenDaysAgo).length;
    return { totalJobs, totalApps, avgAppsPerJob, categoryDist, recentApps };
  }, [jobs, applications, availableCategories]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    const { error } = await supabase.auth.signInWithPassword({
      email: loginForm.username,
      password: loginForm.password,
    });
    if (error) setLoginError('Credenziali non valide.');
    else setView('ADMIN');
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('PUBLIC');
  };

  const handleRemoveJob = async (id: string) => {
    if (!confirm("Eliminare questo annuncio?")) return;
    try {
      const { error } = await supabase.from('jobs').delete().eq('id', id);
      if (error) throw error;
      await fetchData(false);
    } catch (err) {
      console.error("Errore eliminazione:", err);
    }
  };

  const filteredAndSortedJobs = useMemo(() => {
    const filtered = filterType === 'All' 
      ? jobs 
      : jobs.filter(j => j.category === filterType);
    return [...filtered].sort((a, b) => {
      if (a.isFeatured && !b.isFeatured) return -1;
      if (!a.isFeatured && b.isFeatured) return 1;
      return new Date(b.postedAt).getTime() - new Date(a.postedAt).getTime();
    });
  }, [jobs, filterType]);

  const filteredApplications = useMemo(() => {
    return applications.filter(app => {
      const job = jobs.find(j => j.id === app.jobId);
      const categoryMatch = appFilterCategory === 'All' || (job && job.category === appFilterCategory);
      const appDate = new Date(app.appliedAt);
      const startMatch = !appFilterDateStart || appDate >= new Date(appFilterDateStart);
      const endMatch = !appFilterDateEnd || appDate <= new Date(appFilterDateEnd + 'T23:59:59');
      return categoryMatch && startMatch && endMatch;
    });
  }, [applications, jobs, appFilterCategory, appFilterDateStart, appFilterDateEnd]);

  if (isAuthLoading || isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-brand border-t-transparent animate-spin rounded-full"></div>
          <p className="text-slate-500 font-medium animate-pulse">Sincronizzazione in corso...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      {isSubmittingApp && (
        <div className="fixed inset-0 z-[100] bg-white/90 backdrop-blur-md flex items-center justify-center animate-in fade-in duration-300">
          <div className="flex flex-col items-center gap-6 text-center px-4">
            <div className="w-16 h-16 border-4 border-brand border-t-transparent animate-spin rounded-full shadow-lg"></div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900 mb-2">Stiamo inviando la tua candidatura</h2>
              <p className="text-slate-500 font-medium animate-pulse">Attendi qualche secondo, stiamo salvando i tuoi dati...</p>
            </div>
          </div>
        </div>
      )}

      <div className="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[92vw] sm:w-auto">
        <div className="bg-white/80 backdrop-blur-md border border-slate-200 px-1 py-1 shadow-xl flex items-center gap-1 w-full sm:w-auto rounded-none">
          <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view === 'PUBLIC' || view === 'JOB_DETAILS' || view === 'THANK_YOU' ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Posizioni Aperte</button>
          <button onClick={() => setView('ADMIN')} className={`flex-1 sm:flex-none px-4 sm:px-6 py-2.5 text-xs sm:text-sm font-bold transition-all whitespace-nowrap ${view.startsWith('ADMIN') ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'}`}>Area Azienda</button>
        </div>
      </div>

      <main className="pt-8">
        {(view === 'PUBLIC' || (view === 'JOB_DETAILS' && !selectedJob)) && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="mb-12 text-center">
              <h1 className="text-4xl lg:text-5xl font-extrabold text-slate-900 mb-4 tracking-tight">Lavora con noi</h1>
              <p className="text-lg text-slate-600 max-w-2xl mx-auto">Sfoglia le nostre posizioni aperte e trova la tua prossima sfida professionale.</p>
            </div>
            <div className="flex flex-wrap gap-4 mb-10 justify-center">
              <button onClick={() => setFilterType('All')} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === 'All' ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>Tutti</button>
              {availableCategories.map(cat => (
                <button key={cat} onClick={() => setFilterType(cat)} className={`px-5 py-2 text-sm font-semibold transition-all border ${filterType === cat ? 'bg-brand text-white shadow-md border-brand' : 'bg-white text-slate-600 border-slate-200 hover:border-brand'}`}>{cat}</button>
              ))}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-8">
              {filteredAndSortedJobs.length > 0 ? (
                filteredAndSortedJobs.map(job => (
                  <JobCard key={job.id} job={job} onClick={(j) => { setSelectedJob(j); setView('JOB_DETAILS'); }} />
                ))
              ) : (
                <div className="col-span-full py-20 text-center"><p className="text-slate-400 font-medium">Nessuna posizione trovata.</p></div>
              )}
            </div>
          </div>
        )}

        {view === 'JOB_DETAILS' && selectedJob && (
          <div className="w-full px-6 lg:px-20 py-32">
            <button onClick={() => { setView('PUBLIC'); setSelectedJob(null); }} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 mb-8 font-medium group"><span className="group-hover:-translate-x-1 transition-transform"><Icons.ChevronLeft /></span>Torna agli annunci</button>
            <div className="bg-white border border-slate-200 p-8 md:p-16 shadow-sm">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 pb-10 border-b border-slate-100">
                <div>
                  <div className="flex items-center gap-3 mb-4">
                    <span className="inline-block px-3 py-1 text-xs font-bold bg-brand-light text-brand uppercase tracking-widest">{selectedJob.category}</span>
                    {selectedJob.isFeatured && <span className="inline-block px-3 py-1 text-xs font-bold bg-amber-100 text-amber-700 uppercase flex items-center gap-1.5"><Icons.Sparkles /> In Evidenza</span>}
                  </div>
                  <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 mb-2">{selectedJob.title}</h1>
                  <div className="flex flex-wrap gap-6 text-slate-500 font-medium mt-4">
                    <div className="flex items-center gap-2"><Icons.MapPin />{selectedJob.location}</div>
                    <div className="flex items-center gap-2"><Icons.Clock />{selectedJob.type}</div>
                  </div>
                </div>
                <button onClick={() => setIsApplyModalOpen(true)} className="bg-brand text-white px-10 py-5 font-bold text-xl hover:bg-brand-dark transition-all shadow-xl shadow-brand/20">Candidati Ora</button>
              </div>
              <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap mb-10 text-lg">{selectedJob.description}</div>
            </div>
          </div>
        )}

        {view === 'THANK_YOU' && <ThankYou onBack={() => { setView('PUBLIC'); setSelectedJob(null); }} jobTitle={selectedJob?.title} />}

        {view.startsWith('ADMIN') && !isAuthenticated && (
          <div className="max-w-md mx-auto px-4 py-32">
            <div className="bg-white p-8 border border-slate-200 shadow-2xl">
              <div className="text-center mb-8"><div className="inline-flex items-center justify-center w-16 h-16 bg-brand-light text-brand rounded-full mb-4"><Icons.Briefcase /></div><h2 className="text-2xl font-bold text-slate-900">Bentornato</h2><p className="text-slate-500 text-sm">Accedi per gestire la tua bacheca.</p></div>
              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Email</label><input type="email" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="email@azienda.it" value={loginForm.username} onChange={e => setLoginForm({ ...loginForm, username: e.target.value })} /></div>
                <div className="space-y-1"><label className="text-xs font-bold text-slate-500 uppercase">Password</label><input type="password" required className="w-full px-4 py-3 border border-slate-200 focus:ring-2 focus:ring-brand outline-none" placeholder="••••••••" value={loginForm.password} onChange={e => setLoginForm({ ...loginForm, password: e.target.value })} /></div>
                {loginError && <div className="bg-red-50 text-red-500 p-3 text-xs border border-red-100 font-medium">{loginError}</div>}
                <button type="submit" className="w-full py-4 bg-brand text-white font-bold hover:bg-brand-dark transition-all uppercase tracking-widest text-sm shadow-lg shadow-brand/20 mt-4">Accedi</button>
              </form>
            </div>
          </div>
        )}

        {view === 'ADMIN' && isAuthenticated && (
          <AdminModule jobs={jobs} applications={applications} stats={stats} onLogout={handleLogout} onCreateJob={() => setView('ADMIN_CREATE')} onViewApplications={() => setView('ADMIN_APPLICATIONS')} onEditJob={(job) => { setEditingJob(job); setView('ADMIN_EDIT'); }} onRemoveJob={handleRemoveJob} onNavigate={(newView) => setView(newView)} onRefresh={() => fetchData(false)} isRefreshing={isRefreshing} userEmail={userEmail} />
        )}

        {view === 'ADMIN_APPLICATIONS' && isAuthenticated && (
          <div className="w-full px-6 lg:px-12 py-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <button onClick={() => setView('ADMIN')} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 font-medium"><Icons.ChevronLeft />Torna alla Dashboard</button>
              <button onClick={() => fetchData(false)} disabled={isRefreshing} className="text-brand text-sm font-bold flex items-center gap-2 hover:underline disabled:opacity-50"><div className={isRefreshing ? 'animate-spin' : ''}><Icons.Clock /></div>Aggiorna</button>
            </div>
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 mb-12">
              <div><h1 className="text-3xl font-bold text-slate-900">Registro Candidature ({filteredApplications.length})</h1><p className="text-slate-500 mt-1">Gestisci e filtra le persone che hanno risposto ai tuoi annunci.</p></div>
              <div className="flex flex-wrap items-center gap-4 bg-white p-4 border border-slate-200 shadow-sm">
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Categoria</label><select className="px-3 py-2 border border-slate-200 outline-none bg-white text-sm font-medium min-w-[150px]" value={appFilterCategory} onChange={e => setAppFilterCategory(e.target.value)}><option value="All">Tutte</option>{availableCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}</select></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Dal</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateStart} onChange={e => setAppFilterDateStart(e.target.value)} /></div>
                <div className="flex flex-col gap-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Al</label><input type="date" className="px-3 py-2 border border-slate-200 outline-none text-sm" value={appFilterDateEnd} onChange={e => setAppFilterDateEnd(e.target.value)} /></div>
                <div className="flex flex-col gap-1 self-end"><button onClick={() => { setAppFilterCategory('All'); setAppFilterDateStart(''); setAppFilterDateEnd(''); }} className="px-4 py-2 text-xs font-bold text-brand hover:bg-brand-light transition-all border border-brand/20 uppercase tracking-widest">Reset</button></div>
              </div>
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              {filteredApplications.length > 0 ? (
                filteredApplications.map(app => (
                  <div key={app.id} className="bg-white p-8 border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-8 items-start animate-in fade-in slide-in-from-bottom-2">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2"><h3 className="text-xl font-bold text-slate-900">{app.candidateName}</h3><span className="px-2 py-0.5 bg-brand-light text-brand text-[10px] font-bold uppercase rounded">{jobs.find(j => j.id === app.jobId)?.category || 'Altro'}</span></div>
                      <p className="text-sm text-slate-500 font-medium mb-1">Per: <span className="text-slate-900">{jobs.find(j => j.id === app.jobId)?.title || 'Posizione rimossa'}</span></p>
                      <p className="text-sm text-slate-500 font-medium mb-4">{app.email} &bull; {app.phone}</p>
                      <div className="bg-slate-50 p-5 border-l-4 border-brand italic text-slate-600 text-sm">"{app.coverLetter || 'Nessuna lettera.'}"</div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[180px] w-full sm:w-auto">
                      {app.cvFileName ? (
                        <button onClick={() => handleDownloadCV(app)} disabled={loadingCVId === app.id} className={`bg-slate-900 text-white px-6 py-3 text-sm font-bold text-center hover:bg-slate-800 transition-colors uppercase flex items-center justify-center gap-2 ${loadingCVId === app.id ? 'opacity-70' : ''}`}>
                          {loadingCVId === app.id ? <><div className="w-3 h-3 border-2 border-white border-t-transparent animate-spin rounded-full"></div>Recupero...</> : 'Scarica CV'}
                        </button>
                      ) : <div className="bg-slate-100 text-slate-400 px-6 py-3 text-xs font-bold text-center uppercase border border-slate-200">Nessun CV</div>}
                      <p className="text-[10px] text-center text-slate-400 font-bold uppercase">Ricevuto il: {new Date(app.appliedAt).toLocaleDateString('it-IT')}</p>
                    </div>
                  </div>
                ))
              ) : <div className="col-span-full bg-white border border-slate-200 p-20 text-center"><p className="text-slate-400 font-medium">Nessuna candidatura trovata.</p></div>}
            </div>
          </div>
        )}

        {view === 'ADMIN_PROFILE' && isAuthenticated && <CompanyProfile onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {view === 'ADMIN_SETTINGS' && isAuthenticated && <Settings onBack={() => setView('ADMIN')} userEmail={userEmail} />}
        {(view === 'ADMIN_CREATE' || view === 'ADMIN_EDIT') && isAuthenticated && (
          <div className="py-20 px-6 lg:px-12">
            <JobForm 
              initialData={editingJob || undefined} 
              onSubmit={handleAddJob} 
              onCancel={() => setView('ADMIN')} 
              isAiEnabled={isAiEnabled}
            />
          </div>
        )}
      </main>
      {isApplyModalOpen && selectedJob && <ApplicationModal job={selectedJob} isOpen={isApplyModalOpen} onClose={() => setIsApplyModalOpen(false)} onSubmit={handleApply} />}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Job, JobType, JobCategory } from '../types';
import { Icons } from '../constants';
import { generateJobDescription } from '../geminiService';

interface JobFormProps {
  initialData?: Job;
  onSubmit: (job: Omit<Job, 'id' | 'postedAt'>) => void;
  onCancel: () => void;
  isAiEnabled?: boolean;
}

export const JobForm: React.FC<JobFormProps> = ({ initialData, onSubmit, onCancel, isAiEnabled = true }) => {
  const [formData, setFormData] = useState({
    title: '',
    company: '',
    category: JobCategory.TECH as string,
    type: JobType.FULL_TIME,
    location: '',
    description: '',
    requirements: '',
    salaryRange: '',
    isFeatured: false
  });

  const [customCategory, setCustomCategory] = useState('');
  const [isCustomCategory, setIsCustomCategory] = useState(false);

  useEffect(() => {
    if (initialData) {
      const isStandard = Object.values(JobCategory).includes(initialData.category as JobCategory);
      setFormData({
        title: initialData.title,
        company: initialData.company,
        category: isStandard ? initialData.category : 'OTHER',
        type: initialData.type,
        location: initialData.location,
        description: initialData.description,
        requirements: initialData.requirements.join(', '),
        salaryRange: initialData.salaryRange || '',
        isFeatured: initialData.isFeatured || false
      });

      if (!isStandard) {
        setIsCustomCategory(true);
        setCustomCategory(initialData.category);
      }
    }
  }, [initialData]);

  const [isGenerating, setIsGenerating] = useState(false);

  const handleAiAssist = async () => {
    if (!formData.title) {
      alert("Inserisci un titolo per usare l'assistente AI");
      return;
    }
    setIsGenerating(true);
    const catForAi = isCustomCategory ? customCategory : formData.category;
    const generated = await generateJobDescription(formData.title, catForAi, formData.requirements);
    setFormData(prev => ({ ...prev, description: generated || '' }));
    setIsGenerating(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCategory = isCustomCategory ? customCategory.trim() : formData.category;

    if (!finalCategory) {
      alert("Inserisci una categoria valida.");
      return;
    }

    onSubmit({
      ...formData,
      category: finalCategory as any,
      requirements: formData.requirements.split(',').map(r => r.trim())
    });
  };

  return (
    <div className="max-w-3xl mx-auto bg-white p-8 shadow-sm border border-slate-200">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-2xl font-bold text-slate-900">
          {initialData ? 'Modifica Posizione' : 'Nuova Posizione Aperta'}
        </h2>
        <button onClick={onCancel} className="text-slate-400 hover:text-slate-600">
          Annulla
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-brand-light/20 border border-brand/10 p-4 mb-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${formData.isFeatured ? 'bg-amber-500 text-white' : 'bg-slate-200 text-slate-500'}`}>
              <Icons.Sparkles />
            </div>
            <div>
              <p className="text-sm font-bold text-slate-900">Metti in evidenza</p>
              <p className="text-xs text-slate-500">L'annuncio rimarrà in cima alla lista pubblica.</p>
            </div>
          </div>
          <button 
            type="button"
            onClick={() => setFormData({...formData, isFeatured: !formData.isFeatured})}
            className={`w-12 h-6 rounded-full transition-all relative ${formData.isFeatured ? 'bg-brand' : 'bg-slate-300'}`}
          >
            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${formData.isFeatured ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Titolo del lavoro</label>
            <input
              required
              className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
              placeholder="es. Frontend Developer"
              value={formData.title}
              onChange={e => setFormData({ ...formData, title: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Luogo</label>
            <input
              required
              className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
              placeholder="es. Milano / Remote"
              value={formData.location}
              onChange={e => setFormData({ ...formData, location: e.target.value })}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Categoria</label>
            <div className="space-y-3">
              <select
                className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none bg-white"
                value={isCustomCategory ? 'OTHER' : formData.category}
                onChange={e => {
                  if (e.target.value === 'OTHER') {
                    setIsCustomCategory(true);
                    setFormData({ ...formData, category: 'OTHER' });
                  } else {
                    setIsCustomCategory(false);
                    setFormData({ ...formData, category: e.target.value });
                  }
                }}
              >
                {Object.values(JobCategory).map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
                <option value="OTHER">+ Aggiungi categoria personalizzata...</option>
              </select>

              {isCustomCategory && (
                <div className="animate-in fade-in slide-in-from-top-1 duration-200">
                  <input
                    required
                    className="w-full px-4 py-2 border border-brand focus:ring-2 focus:ring-brand outline-none bg-brand-light/20"
                    placeholder="Digita il nome della nuova categoria"
                    value={customCategory}
                    onChange={e => setCustomCategory(e.target.value)}
                  />
                  <p className="text-[10px] text-brand font-bold uppercase mt-1">Nuova categoria dinamica</p>
                </div>
              )}
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-slate-700">Tipo Contratto</label>
            <select
              className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none bg-white"
              value={formData.type}
              onChange={e => setFormData({ ...formData, type: e.target.value as JobType })}
            >
              {Object.values(JobType).map(t => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Azienda (opzionale)</label>
          <input
            className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
            placeholder="Nome azienda"
            value={formData.company}
            onChange={e => setFormData({ ...formData, company: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <label className="text-sm font-semibold text-slate-700">Requisiti Chiave (separati da virgola)</label>
          <input
            className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
            placeholder="es. React, TypeScript, 3 anni esperienza"
            value={formData.requirements}
            onChange={e => setFormData({ ...formData, requirements: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <label className="text-sm font-semibold text-slate-700">Descrizione del lavoro</label>
            {isAiEnabled && (
              <button
                type="button"
                onClick={handleAiAssist}
                disabled={isGenerating}
                className="flex items-center gap-2 text-xs font-bold text-brand hover:text-brand-dark disabled:opacity-50"
              >
                <Icons.Sparkles />
                {isGenerating ? 'Generando...' : 'Aiutami con AI'}
              </button>
            )}
          </div>
          <textarea
            required
            rows={10}
            className="w-full px-4 py-2 border border-slate-200 focus:ring-2 focus:ring-brand outline-none"
            placeholder="Scrivi qui la descrizione..."
            value={formData.description}
            onChange={e => setFormData({ ...formData, description: e.target.value })}
          ></textarea>
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button
            type="button"
            onClick={onCancel}
            className="px-6 py-2 font-medium text-slate-600 hover:bg-slate-50"
          >
            Annulla
          </button>
          <button
            type="submit"
            className="px-6 py-2 font-bold bg-brand text-white hover:bg-brand-dark transition-colors"
          >
            {initialData ? 'Salva Modifiche' : 'Pubblica Annuncio'}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Icons } from '../constants';
import { supabase } from '../supabaseClient';

interface SettingsProps {
  onBack: () => void;
  userEmail?: string;
}

export const Settings: React.FC<SettingsProps> = ({ onBack, userEmail }) => {
  const [settings, setSettings] = useState({
    notifications: false,
    webhookUrl: '',
    aiAssist: true,
  });

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        const { data, error } = await supabase
          .from('company_profiles')
          .select('notifications_enabled, webhook_url, ai_assist_enabled')
          .eq('id', user.id)
          .single();

        if (data) {
          setSettings({
            notifications: data.notifications_enabled || false,
            webhookUrl: data.webhook_url || '',
            aiAssist: data.ai_assist_enabled ?? true
          });
        }
      } catch (err) {
        console.error("Errore caricamento impostazioni:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchSettings();
  }, []);

  const handleSave = async () => {
    setIsSaving(true);
    setSaveSuccess(false);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Sessione scaduta");

      const { error } = await supabase
        .from('company_profiles')
        .upsert({
          id: user.id,
          notifications_enabled: settings.notifications,
          webhook_url: settings.webhookUrl,
          ai_assist_enabled: settings.aiAssist,
          updated_at: new Date().toISOString()
        });

      if (error) throw error;
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      alert("Errore durante il salvataggio.");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="w-full px-6 py-32 flex justify-center">
        <div className="w-8 h-8 border-4 border-brand border-t-transparent animate-spin rounded-full"></div>
      </div>
    );
  }

  return (
    <div className="w-full px-6 lg:px-12 py-20">
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-slate-900 font-medium group">
          <span className="group-hover:-translate-x-1 transition-transform"><Icons.ChevronLeft /></span> Torna alla Dashboard
        </button>
        <button 
          onClick={handleSave}
          disabled={isSaving}
          className="bg-brand text-white px-8 py-3 font-bold text-sm hover:bg-brand-dark transition-all shadow-lg shadow-brand/20 disabled:opacity-50 uppercase tracking-widest"
        >
          {isSaving ? 'Salvataggio...' : saveSuccess ? '✓ Salvato' : 'Salva Modifiche'}
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <div className="bg-white border border-slate-200 shadow-sm overflow-hidden h-fit">
          <div className="p-8 border-b border-slate-100 bg-slate-50/30">
            <h2 className="text-2xl font-bold text-slate-900">Integrazioni & Notifiche</h2>
            <p className="text-sm text-slate-500">Collega la tua bacheca a strumenti esterni come Make.com o Zapier.</p>
          </div>
          <div className="p-8 space-y-10">
            <div className="flex items-center justify-between">
              <div className="flex-1 pr-4">
                <p className="font-bold text-slate-900 text-lg flex items-center gap-2">
                  Notifiche Email & Webhook
                  {settings.notifications && <span className="text-[10px] bg-green-100 text-green-700 px-2 py-0.5 rounded-full uppercase">Attivo</span>}
                </p>
                <p className="text-sm text-slate-500">Invia i dati delle candidature a un indirizzo esterno non appena vengono ricevuti.</p>
              </div>
              <button 
                onClick={() => setSettings({...settings, notifications: !settings.notifications})}
                className={`w-16 h-8 rounded-full transition-all relative shrink-0 ${settings.notifications ? 'bg-brand' : 'bg-slate-300'}`}
              >
                <div className={`absolute top-1.5 w-5 h-5 bg-white rounded-full shadow-sm transition-all ${settings.notifications ? 'left-9' : 'left-1.5'}`}></div>
              </button>
            </div>

            {settings.notifications && (
              <div className="p-8 bg-brand-light/30 border border-brand/10 space-y-6 animate-in slide-in-from-top-2 duration-300">
                <div className="flex items-center gap-4 mb-2">
                  <div className="w-12 h-12 bg-white border border-brand/20 rounded-lg flex items-center justify-center font-bold text-brand italic text-xl shadow-sm">M</div>
                  <div>
                    <p className="text-sm font-bold text-slate-900">Webhook URL (Make.com / Custom)</p>
                    <p className="text-xs text-slate-500">Incolla qui l'URL fornito dal tuo scenario Make.</p>
                  </div>
                </div>
                <input 
                  type="url"
                  className="w-full px-5 py-4 border border-slate-200 focus:ring-2 focus:ring-brand outline-none font-mono text-sm shadow-inner"
